class LRUCache {
public:
    struct Node {
        int key, val;
        Node *left, *right;
        Node(int _key, int _val): key(_key), val(_val), left(NULL), right(NULL) {}
    }*L, *R;
    unordered_map<int, Node*> hash;                              // 哈希表，O(1)查找
    int n;

    void remove(Node* p) {  // 从双向链表中删除节点
        p->right->left = p->left;
        p->left->right = p->right;
    }

    void insert(Node* p) {  // 将节点插入到链表头部（最近使用）
        p->right = L->right;  // 插入头部：连接右邻居
        p->left = L;
        L->right->left = p;
        L->right = p;  // 插入头部：虚拟头节点指向p
    }

    LRUCache(int capacity) {
        n = capacity;
        L = new Node(-1, -1), R = new Node(-1, -1);
        L->right = R, R->left = L;
    }

    int get(int key) {
        if (hash.count(key) == 0) return -1;                     // 查找是否在哈希表中
        auto p = hash[key];
        remove(p);
        insert(p);
        return p->val;
    }

    void put(int key, int value) {
        if (hash.count(key)) {                                   // 查找是否在哈希表中
            auto p = hash[key];
            p->val = value;
            remove(p);
            insert(p);
        } else {
            if (hash.size() == n) {
                auto p = R->left;  // 找到最久未使用的节点（尾节点）
                remove(p);
                hash.erase(p->key);
                delete p;
            }
            auto p = new Node(key, value);
            hash[key] = p;
            insert(p);
        }
    }
};

